# Try mirroring across both center lines
def mirror_both(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0] * cols for _ in range(rows)]

    # Copy original position
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                result[r][c] = 3

    # Mirror horizontally (left-right)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                result[r][cols - 1 - c] = 3

    # Mirror vertically (up-down)  
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                result[rows - 1 - r][c] = 3

    return result

